package com.tehang.enterpriserisk.security;
import com.tehang.enterpriserisk.service.AuthService; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.Map; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class AuthFilter extends OncePerRequestFilter {private final AuthService auth; public AuthFilter(AuthService a){auth=a;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String path=req.getRequestURI();if(path.startsWith("/actuator")||path.equals("/api/auth/login")||path.startsWith("/api/auth/refresh")){chain.doFilter(req,res);return;}String h=req.getHeader("Authorization");if(h==null||!h.startsWith("Bearer ")){res.setStatus(401);res.setContentType("application/json;charset=UTF-8");res.getWriter().write("{\"message\":\"请先登录\"}");return;}final Map<String,String> u;try{u=auth.current(h.substring(7));}catch(Exception e){res.setStatus(401);res.setContentType("application/json;charset=UTF-8");res.getWriter().write("{\"message\":\"登录已过期\"}");return;}req.setAttribute("account",u.get("account"));req.setAttribute("role",u.get("role"));chain.doFilter(req,res);}}
